package it.unicam.cs.mpgc.rpg123015;


import javafx.application.Application;
import javafx.stage.Stage;
import javafx.scene.*;
import javafx.scene.layout.*;
import javafx.scene.image.Image;

import java.util.Objects;


public class App extends Application {

    Scene scena;

    public static void main(String[] args) {
        //metodo sincrono, aspetto che termini launch prima di eseguire il codice dopo
        launch(args);

    }

    @Override
    public void start(Stage primaryStage) throws Exception {

        MainMenu mm = new MainMenu();
        synchronized (scena = mm.mmScene)
        {
            primaryStage.setScene(scena);
            primaryStage.setResizable(false);
            primaryStage.getIcons().add(new Image("/icons/AvatarSprite.png"));
            primaryStage.setTitle("Dungeon Hoards");
            primaryStage.show();
        }


    }

}
